import torch
import torch.nn as nn

class Classifier(nn.Module):
    def __init__(self, input_dim=128, num_classes=10):
        super().__init__()
        self.network = nn.Sequential(nn.Linear(input_dim, 256), nn.ReLU(), nn.Linear(256, num_classes))

    def forward(self, x):
        return self.network(x)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
model = Classifier().to(device)
state = torch.load("model_weights.pt", map_location=device, weights_only=True)
model.load_state_dict(state)
model.eval()

def predict(features):
    if features.ndim != 2 or features.shape[1] != 128:
        raise ValueError("Expected a tensor shaped [batch_size, 128]")
    features = features.to(device)
    with torch.inference_mode():
        logits = model(features)
        probabilities = torch.softmax(logits, dim=-1)
        predictions = probabilities.argmax(dim=-1)
    return predictions.cpu(), probabilities.cpu()

