import torch
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

class PredictionRequest(BaseModel):
    features: list[float] = Field(min_length=128, max_length=128)

class PredictionResponse(BaseModel):
    predicted_class: int
    probabilities: list[float]

@asynccontextmanager
async def lifespan(app: FastAPI):
    app.state.model = Classifier()
    state = torch.load("model_weights.pt", map_location="cpu", weights_only=True)
    app.state.model.load_state_dict(state)
    app.state.model.eval()
    yield

app = FastAPI(title="Model Inference API", lifespan=lifespan)

@app.get("/health")
def health():
    return {"status": "ok"}

@app.post("/predict", response_model=PredictionResponse)
def predict(request: PredictionRequest):
    try:
        features = torch.tensor(request.features, dtype=torch.float32).unsqueeze(0)
        with torch.inference_mode():
            logits = app.state.model(features)
            probabilities = torch.softmax(logits, dim=-1)[0]
        return PredictionResponse(predicted_class=int(probabilities.argmax()), probabilities=probabilities.tolist())
    except (RuntimeError, ValueError) as exc:
        raise HTTPException(status_code=500, detail="Inference failed") from exc
